<?php
require_once __DIR__.'/includes/bootstrap.php';
$slug=trim((string)($_GET['slug']??''));$course=null;$lessons=[];if($slug!==''){try{$q=$db->prepare("SELECT c.*,lc.name category_name FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.slug=? AND c.enabled=1 LIMIT 1");$q->execute([$slug]);$course=$q->fetch(PDO::FETCH_ASSOC)?:null;if($course){$q=$db->prepare('SELECT * FROM learning_lessons WHERE course_id=? AND enabled=1 ORDER BY sort_order,id');$q->execute([(int)$course['id']]);$lessons=$q->fetchAll(PDO::FETCH_ASSOC);}}catch(Throwable){}}
if(!$course){http_response_code(404);exit('Course not found.');}$user=lh_user();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=lh_h($course['title'])?> — Learning Hub</title><style>body{margin:0;font-family:Inter,Arial;background:#f7f9fd;color:#172033}.wrap{width:min(900px,calc(100% - 28px));margin:auto}.hero{padding:45px 0 30px}.back{color:#635bff;font-size:13px;font-weight:800}.hero h1{font-size:42px;letter-spacing:-2px;margin:18px 0 8px}.hero p{color:#707b8e;line-height:1.7}.tag{display:inline-block;background:#eeedff;color:#635bff;padding:7px 10px;border-radius:999px;font-size:11px;font-weight:800}.lessons{display:grid;gap:10px;padding-bottom:50px}.lesson{display:flex;align-items:center;gap:15px;background:#fff;border:1px solid #e5e8ef;border-radius:14px;padding:17px}.num{width:35px;height:35px;border-radius:10px;background:#f0efff;display:grid;place-items:center;font-weight:900;color:#635bff}.lesson h3{margin:0;font-size:15px}.lesson small{color:#707b8e}.empty{background:#fff;border:1px solid #e5e8ef;border-radius:16px;padding:25px;color:#707b8e}</style></head><body><main class="wrap"><section class="hero"><a class="back" href="/learning-hub/courses.php">← All courses</a><br><br><span class="tag"><?=lh_h($course['category_name']??'Course')?> · <?=lh_h($course['level'])?></span><h1><?=lh_h($course['title'])?></h1><p><?=lh_h($course['description']??'Follow the lessons below to complete this course.')?></p></section><section class="lessons"><?php foreach($lessons as $i=>$lesson):?><a class="lesson" href="/learning-hub/lesson.php?id=<?=urlencode((string)$lesson['id'])?>"><span class="num"><?=($i+1)?></span><div><h3><?=lh_h($lesson['title'])?></h3><small>Open lesson →</small></div></a><?php endforeach;if(!$lessons):?><div class="empty">Lessons haven't been published for this course yet.</div><?php endif;?></section></main></body></html>
